import{_ as e,o as a,c as o,ae as d}from"./chunks/framework.Dh1jimFm.js";const p=JSON.parse('{"title":"Tag Validation","description":"","frontmatter":{},"headers":[],"relativePath":"qa/tag-validation.md","filePath":"qa/tag-validation.md"}'),r={name:"qa/tag-validation.md"};function l(s,t,i,n,c,g){return a(),o("div",null,t[0]||(t[0]=[d('<h1 id="tag-validation" tabindex="-1">Tag Validation <a class="header-anchor" href="#tag-validation" aria-label="Permalink to &quot;Tag Validation&quot;">​</a></h1><p>When working with formatted documents or CAT tool files, <strong>tags must be preserved</strong>.</p><h2 id="why-tags-matter" tabindex="-1">Why tags matter <a class="header-anchor" href="#why-tags-matter" aria-label="Permalink to &quot;Why tags matter&quot;">​</a></h2><p>Tags represent formatting or placeholders. If tags are missing or unbalanced, reimporting into your CAT tool can fail or formatting may be lost.</p><h2 id="tag-display-modes" tabindex="-1">Tag display modes <a class="header-anchor" href="#tag-display-modes" aria-label="Permalink to &quot;Tag display modes&quot;">​</a></h2><p>Supervertaler supports two ways of viewing formatting:</p><ul><li><strong>WYSIWYG mode</strong>: shows <em>bold/italic/underline</em> as formatting</li><li><strong>Tag view</strong>: shows the raw markup (for example <code>&lt;b&gt;...&lt;/b&gt;</code>)</li></ul><p>Use <strong>Tag view</strong> when you are preparing to export/reimport and you want to verify the raw tags.</p><h2 id="supported-formatting-tags" tabindex="-1">Supported formatting tags <a class="header-anchor" href="#supported-formatting-tags" aria-label="Permalink to &quot;Supported formatting tags&quot;">​</a></h2><p>These tags are commonly used in Supervertaler projects:</p><table tabindex="0"><thead><tr><th>Tag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>&lt;b&gt;...&lt;/b&gt;</code></td><td>Bold</td></tr><tr><td><code>&lt;i&gt;...&lt;/i&gt;</code></td><td>Italic</td></tr><tr><td><code>&lt;u&gt;...&lt;/u&gt;</code></td><td>Underline</td></tr><tr><td><code>&lt;bi&gt;...&lt;/bi&gt;</code></td><td>Bold + Italic</td></tr><tr><td><code>&lt;sub&gt;...&lt;/sub&gt;</code></td><td>Subscript</td></tr><tr><td><code>&lt;sup&gt;...&lt;/sup&gt;</code></td><td>Superscript</td></tr></tbody></table><h2 id="cat-tool-placeholder-tags" tabindex="-1">CAT tool placeholder tags <a class="header-anchor" href="#cat-tool-placeholder-tags" aria-label="Permalink to &quot;CAT tool placeholder tags&quot;">​</a></h2><p>CAT tools use placeholders/tags that must be preserved exactly:</p><table tabindex="0"><thead><tr><th>CAT tool</th><th>Examples</th></tr></thead><tbody><tr><td>memoQ</td><td><code>{1}</code>, <code>[2}...{2]</code>, <code>{MQ}</code>, <code>{tspan}</code></td></tr><tr><td>Trados Studio</td><td><code>&lt;1&gt;</code>, <code>&lt;/1&gt;</code>, <code>&lt;2/&gt;</code></td></tr><tr><td>Phrase (Memsource)</td><td><code>{1}</code>, <code>{2}</code></td></tr></tbody></table><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Keep tags balanced (for example <code>&lt;b&gt;text&lt;/b&gt;</code>, not <code>&lt;b&gt;text</code>).</li><li>If you’re unsure, switch to Tag View and verify the raw tags.</li><li>Don’t change tag numbers or names (for example <code>{1}</code> → <code>{2}</code>), even if the translation “looks fine”.</li><li>If you insert a TM match, double-check that tags/placeholders still match the source.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>For CAT tool workflows, don’t delete or edit placeholder tags unless you know exactly what they represent.</p></div>',17)]))}const u=e(r,[["render",l]]);export{p as __pageData,u as default};
